from itertools import permutations

def solve(facts):
    jobs = facts['jobs']
    n = len(jobs)
    best = None
    result = None

    def visit(used, time, cost, order, starts):
        nonlocal best, result
        if len(order) == n:
            key = (cost, time, tuple(order))
            if best is None or key < best:
                best = key
                result = {'order': list(order), 'starts': list(starts), 'finish': time, 'weighted_tardiness': cost}
            return
        for job in jobs:
            jid = job['id']
            if jid in used or not all(p in used for p in job['predecessors']):
                continue
            start = max(time, job['release'])
            finish = start + job['duration']
            visit(used | {jid}, finish,
                  cost + job['weight'] * max(0, finish - job['due']),
                  order + [jid], starts + [start])

    visit(set(), 0, 0, [], [])
    if result is None:
        raise ValueError('No feasible order')
    return result

def check(answer, facts):
    try:
        if not isinstance(answer, dict) or set(answer) != {'order', 'starts', 'finish', 'weighted_tardiness'}:
            return False
        jobs = facts['jobs']
        best_key = None
        best_answer = None
        for sequence in permutations(jobs):
            positions = {job['id']: i for i, job in enumerate(sequence)}
            if any(p not in positions or positions[p] >= i
                   for i, job in enumerate(sequence)
                   for p in job['predecessors']):
                continue
            elapsed_work = 0
            idle = 0
            starts = []
            tardiness = 0
            for job in sequence:
                idle = max(idle, job['release'] - elapsed_work)
                starts.append(elapsed_work + idle)
                elapsed_work += job['duration']
                completion = elapsed_work + idle
                tardiness += job['weight'] * max(0, completion - job['due'])
            finish = elapsed_work + idle
            order = [job['id'] for job in sequence]
            key = (tardiness, finish, tuple(order))
            if best_key is None or key < best_key:
                best_key = key
                best_answer = {'order': order, 'starts': starts, 'finish': finish, 'weighted_tardiness': tardiness}
        return best_answer is not None and answer == best_answer
    except Exception:
        return False
